import express from "express";
import path from "path";
import fs from "fs";
import { createServer as createViteServer } from "vite";

const app = express();
const PORT = 3000;

app.use(express.json({ limit: "50mb" }));

// Directory for persistent file storage
const DATA_DIR = path.join(process.cwd(), "data");
const BANKS_FILE = path.join(DATA_DIR, "banks.json");

if (!fs.existsSync(DATA_DIR)) {
  fs.mkdirSync(DATA_DIR, { recursive: true });
}

// In-memory cache for fast access
let savedBanksCache: any[] | null = null;

// Helper to load banks
function loadBanks() {
  if (savedBanksCache) return savedBanksCache;
  if (fs.existsSync(BANKS_FILE)) {
    try {
      const content = fs.readFileSync(BANKS_FILE, "utf-8");
      savedBanksCache = JSON.parse(content);
      return savedBanksCache;
    } catch (err) {
      console.error("Error reading banks.json:", err);
    }
  }
  return null;
}

// Helper to save banks
function saveBanks(banks: any[]) {
  savedBanksCache = banks;
  try {
    fs.writeFileSync(BANKS_FILE, JSON.stringify(banks, null, 2), "utf-8");
  } catch (err) {
    console.error("Error writing banks.json:", err);
  }
}

// Share codes memory store
const shareStore: Record<string, any> = {};

// API Routes
app.get("/api/banks", (req, res) => {
  const banks = loadBanks();
  res.json({
    success: true,
    banks: banks || null
  });
});

app.post("/api/banks", (req, res) => {
  const { banks } = req.body;
  if (!Array.isArray(banks)) {
    return res.status(400).json({ success: false, error: "Danh sách ngân hàng không hợp lệ" });
  }

  saveBanks(banks);
  res.json({
    success: true,
    message: "Đã lưu thành công lên máy chủ! Mọi thiết bị kết nối đều có thể xem dữ liệu này.",
    updatedAt: new Date().toISOString()
  });
});

// Share Question Bank API
app.post("/api/share", (req, res) => {
  const { bank } = req.body;
  if (!bank || !bank.title) {
    return res.status(400).json({ success: false, error: "Dữ liệu bộ đề không hợp lệ" });
  }

  // Generate 6-digit share code
  const code = Math.floor(100000 + Math.random() * 900000).toString();
  shareStore[code] = {
    ...bank,
    sharedAt: new Date().toISOString()
  };

  res.json({
    success: true,
    code,
    message: `Mã chia sẻ: ${code}`
  });
});

app.get("/api/share/:code", (req, res) => {
  const code = req.params.code;
  const bank = shareStore[code];
  if (!bank) {
    return res.status(404).json({ success: false, error: "Không tìm thấy bộ đề với mã chia sẻ này" });
  }
  res.json({ success: true, bank });
});

// Health check
app.get("/api/health", (req, res) => {
  res.json({ status: "ok", timestamp: new Date().toISOString() });
});

// Vite Middleware & Static handling
async function startServer() {
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
